    const modalBase=RF.UI.modalHtml.bind(RF.UI);
    RF.UI.modalHtml=function(s){if(this.modal?.type==='v1054Market')return V.modalHtml(s);return modalBase(s)};

    const bindBase=RF.UI.bind.bind(RF.UI);
